//go:build riscv64

package floats

// Add32, Sub32, Mul32, Div32 and Sqrt32 RVV kernels (binop32.go), generated by
// go-asmgen (binop32_riscv64_gen.go) into binop32_riscv64.s, gated on hasRVV
// (kernels_riscv64.go). Strip-mined by VSETVLI, so any vector length gives the
// same result. One IEEE binary32 operation per element, no fused instruction:
// bit-identical to the portable loops. The callers pass every slice already
// sliced to the common length; an empty one never reaches a kernel (the loops
// need n >= 1).
//
//go:noescape
func add32RVV(dst, a, b *float32, n int)

//go:noescape
func sub32RVV(dst, a, b *float32, n int)

//go:noescape
func mul32RVV(dst, a, b *float32, n int)

//go:noescape
func div32RVV(dst, a, b *float32, n int)

//go:noescape
func sqrt32RVV(dst, src *float32, n int)

func add32(dst, a, b []float32) {
	if len(a) == 0 || !hasRVV {
		add32Ref(dst, a, b)
		return
	}
	add32RVV(&dst[0], &a[0], &b[0], len(a))
}

func sub32(dst, a, b []float32) {
	if len(a) == 0 || !hasRVV {
		sub32Ref(dst, a, b)
		return
	}
	sub32RVV(&dst[0], &a[0], &b[0], len(a))
}

func mul32(dst, a, b []float32) {
	if len(a) == 0 || !hasRVV {
		mul32Ref(dst, a, b)
		return
	}
	mul32RVV(&dst[0], &a[0], &b[0], len(a))
}

func div32(dst, a, b []float32) {
	if len(a) == 0 || !hasRVV {
		div32Ref(dst, a, b)
		return
	}
	div32RVV(&dst[0], &a[0], &b[0], len(a))
}

func sqrt32(dst, src []float32) {
	if len(src) == 0 || !hasRVV {
		sqrt32Ref(dst, src)
		return
	}
	sqrt32RVV(&dst[0], &src[0], len(src))
}
